import{_ as i,o as a,c as t,ag as d}from"./chunks/framework.CPvOxTBX.js";const c=JSON.parse('{"title":"发音与发音包","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/pronunciation.md","filePath":"zh/guide/pronunciation.md","lastUpdated":1793115940000}'),e={name:"zh/guide/pronunciation.md"};function h(n,s,l,p,o,k){return a(),t("div",null,s[0]||(s[0]=[d(`<h1 id="发音与发音包" tabindex="-1">发音与发音包 <a class="header-anchor" href="#发音与发音包" aria-label="Permalink to &quot;发音与发音包&quot;">​</a></h1><p>词悦有两种发音来源：<strong>发音包</strong>（<code>.mdd</code> 里的录音）和 <strong>TTS</strong>（系统语音合成）。</p><h2 id="三种发音模式" tabindex="-1">三种发音模式 <a class="header-anchor" href="#三种发音模式" aria-label="Permalink to &quot;三种发音模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td>优先音频包，TTS 兜底</td><td>先找音频包里的录音，找不到就用 TTS 朗读</td></tr><tr><td>仅音频包</td><td>只播录音，没有就直接静音，不会朗读</td></tr><tr><td>仅 TTS</td><td>不使用音频包，一律朗读</td></tr></tbody></table><p>音频包可以在 设置 → 发音 → 发音包 里添加，支持多个，拖动可以调整优先级。</p><h2 id="哪些格式能播" tabindex="-1">哪些格式能播 <a class="header-anchor" href="#哪些格式能播" aria-label="Permalink to &quot;哪些格式能播&quot;">​</a></h2><p>决定能不能出声的不是词悦，而是<strong>系统解码器</strong>（Android 用的是 MediaPlayer）。</p><table tabindex="0"><thead><tr><th>格式</th><th>情况</th></tr></thead><tbody><tr><td>MP3</td><td>最稳，推荐</td></tr><tr><td>WAV（PCM）</td><td>稳；ADPCM、μ-law、A-law 的 WAV 取决于设备</td></tr><tr><td>AAC / M4A</td><td>Android 原生支持，ADTS（裸 <code>.aac</code>）与 MP4 容器都可以</td></tr><tr><td>OGG Vorbis</td><td>支持</td></tr><tr><td>Ogg Speex（<code>.spx</code>）</td><td><strong>不支持</strong>，Android 没有 Speex 解码器</td></tr><tr><td>Opus</td><td>取决于系统版本与容器，Ogg Opus 在较旧系统上不可靠</td></tr></tbody></table><p><code>.spx</code> 是最容易踩到的一个坑。</p><p>WAV 也一样，扩展名说明不了里面是什么：<code>fmt</code> 字段可能是 PCM、ADPCM、μ-law，也可能是<strong>内嵌 MP3</strong>（<code>fmt=0x55</code>）。最后一种在实测设备上能正常播放——系统会把它交给 MP3 解码器，所以看到 <code>.wav</code> 不必先怀疑格式，先按下一节确认日志里有没有 <code>Playing sound</code>。</p><h2 id="点了没声音怎么办" tabindex="-1">点了没声音怎么办 <a class="header-anchor" href="#点了没声音怎么办" aria-label="Permalink to &quot;点了没声音怎么办&quot;">​</a></h2><p>两种情况：</p><p><strong>弹出了「该词典的发音音频使用了此设备不支持的格式」</strong> 说明资源找到了、也交给了解码器，但系统解不了这个格式。看下一节转换。</p><p><strong>完全没反应，也没有提示</strong> 说明这个 <code>sound://</code> 链接没有指向一个存在的资源（词典里的文件名和 <code>.mdd</code> 里的实际路径对不上，或者这本词典根本没有发音资源）。可以用 <code>adb logcat | grep -E &quot;Playing sound|Failed to play audio bytes&quot;</code> 确认点击到底有没有走到播放。</p><h2 id="把不支持的发音包换成能播的格式" tabindex="-1">把不支持的发音包换成能播的格式 <a class="header-anchor" href="#把不支持的发音包换成能播的格式" aria-label="Permalink to &quot;把不支持的发音包换成能播的格式&quot;">​</a></h2><p>关键前提：<strong>如果不修改mdx文件中的内容，那就不要改mdd包中的文件名</strong>。词条正文里写的是 <code>sound://ID1234.spx</code> 这样的引用，改扩展名之后链接就指向了一个不存在的资源，会变成「点了没反应」，比原来更糟。</p><p>好在 <code>Ogg Speex</code> 和 <code>Ogg Vorbis</code> 用的是同一个容器，所以可以把 <code>.spx</code> 里的内容换成 Vorbis，<strong>文件名保持 <code>.spx</code></strong>：容器一致、扩展名一致、词悦传的 MIME（<code>audio/ogg</code>）也仍然正确，Android 就能正常解码。</p><h3 id="_1-解包" tabindex="-1">1. 解包 <a class="header-anchor" href="#_1-解包" aria-label="Permalink to &quot;1. 解包&quot;">​</a></h3><p>图形界面用 MdxExport（Windows），选中 <code>.mdd</code> 导出到一个文件夹；命令行用 <code>mdict-utils</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mdict-utils</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict-utils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mddunpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 词典.mdd</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 分卷则是 词典.1.mdd、词典.2.mdd……逐个解</span></span></code></pre></div><blockquote><p>有些词典把插图和发音放在同一个 <code>.mdd</code> 里，解包后请保留全部文件，只处理音频。</p></blockquote><h3 id="_2-转换-原地替换-文件名不变" tabindex="-1">2. 转换（原地替换，文件名不变） <a class="header-anchor" href="#_2-转换-原地替换-文件名不变" aria-label="Permalink to &quot;2. 转换（原地替换，文件名不变）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 把 Ogg Speex 换成 Ogg Vorbis，输出仍写回 .spx 文件名</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -iname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*.spx&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -print0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> IFS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  ffmpeg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nostdin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -loglevel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> error</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -c:a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libvorbis</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q:a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ac</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 22050</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ogg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.tmp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">%</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}.tmp&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span></code></pre></div><p>参数说明：</p><ul><li><code>-f ogg</code> 必须显式指定，否则 ffmpeg 会因为输出扩展名是 <code>.spx</code> 而找不到容器</li><li><code>-ac 1 -ar 22050</code>：单词读音单声道 22.05 kHz 足够，体积约为原来的两倍以内</li><li><code>-q:a 3</code>：Vorbis 的质量档，3 对语音已经够用</li></ul><p>转换完可以抽查一个文件确认：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 某个文件.spx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 应显示 &quot;Ogg data, Vorbis audio&quot;</span></span></code></pre></div><h3 id="_3-打包" tabindex="-1">3. 打包 <a class="header-anchor" href="#_3-打包" aria-label="Permalink to &quot;3. 打包&quot;">​</a></h3><p>图形界面用 MdxBuilder，类型选 <strong>MDD</strong>，源目录选解包出来的文件夹，输出同名 <code>.mdd</code>；命令行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mdict-utils</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mddpack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./解包目录</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 词典.mdd</span></span></code></pre></div><p>分卷的话按原来的卷号分别打包（<code>.1.mdd</code>、<code>.2.mdd</code>……），卷数不必和原来一致，但同一个卷里的文件顺序最好保持不变。</p><h3 id="_4-放回并重新添加" tabindex="-1">4. 放回并重新添加 <a class="header-anchor" href="#_4-放回并重新添加" aria-label="Permalink to &quot;4. 放回并重新添加&quot;">​</a></h3><p>替换掉原来的 <code>.mdd</code>（或放到任意目录），在 设置 → 发音 → 发音包 里移除旧的、添加新的，然后查词试听。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>改了扩展名，mdx文件却还是不变</strong>：<code>.mdx</code> 里的 <code>sound://…spx</code> 不会跟着变，链接直接失效。要么保持扩展名（推荐上面的 Vorbis 方案），要么连 <code>.mdx</code> 一起重打包。</li><li><strong>只改了部分文件</strong>：同一本词典里可能混着 <code>.spx</code> 和 <code>.mp3</code>，转之前先 <code>find . -type f | sed &#39;s/.*\\.//&#39; | sort | uniq -c</code> 看一眼。</li><li><strong>路径分隔符</strong>：MDD 里的路径可能是 <code>\\img\\a.spx</code> 也可能是 <code>/img/a.spx</code>，重新打包时保持原样，不要手改。</li><li><strong>发音包和正文词典是两回事</strong>：正文词典的 <code>.mdd</code> 里的声音，只要词条里有 <code>sound://</code> 链接就能直接播，不需要在设置里「添加发音包」；「添加发音包」是给「查任意单词都能按键朗读」这个功能用的。</li></ul>`,35)]))}const g=i(e,[["render",h]]);export{c as __pageData,g as default};
